        "Charles L. Sawyers"
      ],
      "assessment": {
        "nobel_worthiness": "BCR-ABL inhibition provided a defining proof that a molecular lesion can be selectively and durably targeted to transform cancer treatment.",
        "attribution": "Druker, Lydon, and Sawyers provide a coherent account spanning drug development, clinical demonstration, and resistance biology.",
        "maturity": "Long clinical follow-up has confirmed a durable change in the management and prognosis of chronic myeloid leukemia.",
        "uncertainties": [
          "Credit for the underlying BCR-ABL discovery and for the therapeutic advance can be separated in more than one defensible way."
        ]
      }
    },
